window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-672217e550266577"]={"versions": [{"id": "FIG-672217e550266577", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Veranschaulichung von Metamodell-Konzepten im AUTOSAR-Standard („Interoperability of AUTOSAR Tools“). Dargestellt ist der Kontext eines Teilmodells („Lower partial model“) zur Erkennung von Modelländerungen bei spaltbaren Aggregationen („Modification detection - meta classes aggregated as «atp.splitable»“).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Innerhalb des umrahmenden Modellkontexts „Lower partial model“ sind zwei Metaklassen definiert:</p>\n<ul class=\"fig-list\"><li>Metaklasse <code>A</code>: Stereotyp bzw. Spezialisierung <code>Identifiable</code>, farblich hervorgehoben (gelb/orange).\n</li><li>Metaklasse <code>C</code>: Stereotyp bzw. Spezialisierung <code>Identifiable</code>, hell hinterlegt.\n</li><li>Beziehung: Kompositionsbeziehung (gefüllte Raute an Metaklasse <code>A</code>), gerichtet auf Metaklasse <code>C</code>, annotiert mit dem Stereotyp <code>«atpSplitable»</code>. Beide Klassen verfügen über ein durch eine horizontale Trennlinie abgesetztes, leeres Attributfach.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablauf- oder Sequenzpfade. Das Diagramm spezifiziert die strukturelle Modellierungsregel, dass Elemente der Metaklasse <code>C</code> über eine als <code>«atpSplitable»</code> gekennzeichnete Komposition in Metaklasse <code>A</code> aggregiert werden können, wodurch Instanzen über mehrere physische ARXML-Dateien bzw. Teilmodelle hinweg aufgeteilt (gesplittet) werden dürfen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für AUTOSAR-Autorendateien, Modell-Merge-Werkzeuge und Werkzeugketten zur Interoperabilität: Aggregationen mit dem Stereotyp <code>«atpSplitable»</code> erlauben das Zerteilen und Zusammenführen partieller Modelle. Werkzeuge zur Änderungserkennung müssen Instanzen der aggregierten identifizierbaren Metaklasse <code>C</code> anhand ihres eindeutigen Bezeichners modellübergreifend abgleichen und zuordnen, auch wenn sie in getrennten Teilmodellen (Partial Models) vorliegen.</p>"}, {"id": "FIG-680a42b7fa04bc2c", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Veranschaulichung von Metamodell-Konzepten im AUTOSAR-Standard („Interoperability of AUTOSAR Tools“). Dargestellt ist der Kontext eines Teilmodells („Lower partial model“) zur Erkennung von Modelländerungen bei spaltbaren Aggregationen („Modification detection - meta classes aggregated as «atp.splitable»“).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Innerhalb des umrahmenden Modellkontexts „Lower partial model“ sind zwei Metaklassen definiert:</p>\n<ul class=\"fig-list\"><li>Metaklasse <code>A</code>: Stereotyp bzw. Spezialisierung <code>Identifiable</code>, farblich hervorgehoben (gelb/orange).\n</li><li>Metaklasse <code>C</code>: Stereotyp bzw. Spezialisierung <code>Identifiable</code>, hell hinterlegt.\n</li><li>Beziehung: Kompositionsbeziehung (gefüllte Raute an Metaklasse <code>A</code>), gerichtet auf Metaklasse <code>C</code>, annotiert mit dem Stereotyp <code>«atpSplitable»</code>. Beide Klassenkästen sind einteilig ohne horizontale Trennlinie für Attributfächer ausgeführt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablauf- oder Sequenzpfade. Das Diagramm spezifiziert die strukturelle Modellierungsregel, dass Elemente der Metaklasse <code>C</code> über eine als <code>«atpSplitable»</code> gekennzeichnete Komposition in Metaklasse <code>A</code> aggregiert werden können, wodurch Instanzen über mehrere physische ARXML-Dateien bzw. Teilmodelle hinweg aufgeteilt (gesplittet) werden dürfen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für AUTOSAR-Autorendateien, Modell-Merge-Werkzeuge und Werkzeugketten zur Interoperabilität: Aggregationen mit dem Stereotyp <code>«atpSplitable»</code> erlauben das Zerteilen und Zusammenführen partieller Modelle. Werkzeuge zur Änderungserkennung müssen Instanzen der aggregierten identifizierbaren Metaklasse <code>C</code> anhand ihres eindeutigen Bezeichners modellübergreifend abgleichen und zuordnen, auch wenn sie in getrennten Teilmodellen (Partial Models) vorliegen.</p>"}], "trans": [{"from": "FIG-672217e550266577", "to": "FIG-680a42b7fa04bc2c", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Metaklassen <code>A</code> und <code>C</code>: Die horizontale Trennlinie zwischen dem oberen Namens-/Stereotypbereich und dem leeren Attributbereich innerhalb der Klassenkästen wurde entfernt.\n</li></ul>"}]};
